    public const string RateLimitCheck = """"
        #!/usr/bin/env python3
        """Login rate-limit check. Generated by PipelineForge.

        Sends repeated failed logins for a probe account and expects the application to answer with a
        throttling or lockout status (EXPECTED_STATUSES) before ATTEMPTS is reached. Never point
        TEST_USERNAME at a real account: it will be locked out.
        """
        import json
        import os
        import sys
        import time
        import urllib.error
        import urllib.parse
        import urllib.request


        class NoRedirect(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, *args, **kwargs):
                return None


        def login_request(url, fmt, user_field, pass_field, username, password):
            if fmt == "json":
                body = json.dumps({user_field: username, pass_field: password}).encode()
                ctype = "application/json"
            else:
                body = urllib.parse.urlencode({user_field: username, pass_field: password}).encode()
                ctype = "application/x-www-form-urlencoded"
            return urllib.request.Request(url, data=body, method="POST", headers={"Content-Type": ctype, "User-Agent": "PipelineForge-ratelimit"})


        def main():
            url = os.environ["TARGET_URL"].rstrip("/") + os.environ.get("LOGIN_PATH", "/login")
            attempts = int(os.environ.get("ATTEMPTS", "20"))
            expected = {int(s) for s in os.environ.get("EXPECTED_STATUSES", "429,423").split(",") if s}
            opener = urllib.request.build_opener(NoRedirect)
            statuses = []
            for i in range(1, attempts + 1):
                req = login_request(url, os.environ.get("LOGIN_FORMAT", "form"), os.environ.get("USERNAME_FIELD", "username"),
                                    os.environ.get("PASSWORD_FIELD", "password"), os.environ.get("TEST_USERNAME", "pf-ratelimit-probe"),
                                    f"wrong-password-{i}-{time.time_ns()}")
                try:
                    with opener.open(req, timeout=15) as resp:
                        status = resp.status
                except urllib.error.HTTPError as err:
                    status = err.code
                except urllib.error.URLError as err:
                    print(f"Login endpoint unreachable: {err.reason}")
                    return 2
                statuses.append(status)
                if status in expected:
                    print(f"Rate limiting works: attempt {i} returned {status}.")
                    write_report(url, statuses, True)
                    return 0
            print(f"No throttling after {attempts} failed logins (statuses: {sorted(set(statuses))}). Expected one of {sorted(expected)}.")
            write_report(url, statuses, False)
            return 1


        def write_report(url, statuses, ok):
            os.makedirs("reports", exist_ok=True)
            env = os.environ.get("DAST_ENV", "env")
            with open(f"reports/rate-limit-{env}.json", "w", encoding="utf-8") as fh:
                json.dump({"url": url, "statuses": statuses, "passed": ok}, fh, indent=2)


        if __name__ == "__main__":
            sys.exit(main())
        """";

    public const string AccessControlCheck = """"
        #!/usr/bin/env python3
        """Two-role access-control and session check. Generated by PipelineForge.

        Logs in as the low-privileged user and as the admin, then checks that:
          * the user role is refused on every admin-only path (broken access control, OWASP A01)
          * anonymous requests are refused on admin-only paths
          * the session cookie changes on login (session fixation)
          * logout invalidates the session
          * session tokens are unique and long enough (token entropy)
        Writes reports/access-control-<env>.json and .sarif, and exits 1 on any failure.
        """
        import http.cookiejar
        import json
        import math
        import os
        import sys
        import urllib.error
        import urllib.parse
        import urllib.request

        DENIED = {401, 403, 404}


        class NoRedirect(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, *args, **kwargs):
                return None


        class Session:
            def __init__(self, base):
                self.base = base
                self.jar = http.cookiejar.CookieJar()
                self.bearer = None
                self.opener = urllib.request.build_opener(NoRedirect, urllib.request.HTTPCookieProcessor(self.jar))

            def request(self, path, data=None, ctype=None, method=None):
                headers = {"User-Agent": "PipelineForge-access-control"}
                if ctype:
                    headers["Content-Type"] = ctype
                if self.bearer:
                    headers["Authorization"] = "Bearer " + self.bearer
                req = urllib.request.Request(self.base + path, data=data, headers=headers, method=method)
                try:
                    with self.opener.open(req, timeout=20) as resp:
                        return resp.status, resp.headers, resp.read(200_000)
                except urllib.error.HTTPError as err:
                    return err.code, err.headers, err.read(200_000)

            def cookies(self):
                return {c.name: c.value for c in self.jar}


        def env(name, default=""):
            return os.environ.get(name, default)


        def login(base, username, password, session=None):
            s = session or Session(base)
            fmt = env("LOGIN_FORMAT", "form")
            fields = {env("USERNAME_FIELD", "username"): username, env("PASSWORD_FIELD", "password"): password}
            if fmt == "json":
                status, _, body = s.request(env("LOGIN_PATH", "/login"), json.dumps(fields).encode(), "application/json", "POST")
                try:
                    data = json.loads(body or b"{}")
                    token = data.get("access_token") or data.get("token") if isinstance(data, dict) else None
                    if isinstance(token, str):
                        s.bearer = token
                except ValueError:
                    pass
            else:
                status, _, _ = s.request(env("LOGIN_PATH", "/login"), urllib.parse.urlencode(fields).encode(), "application/x-www-form-urlencoded", "POST")
            return s, status


        def is_redirect_to_login(status, headers):
            return status in (301, 302, 303, 307, 308) and env("LOGIN_PATH", "/login") in (headers.get("Location") or "")


        def denied(status, headers):
            return status in DENIED or is_redirect_to_login(status, headers)


        def entropy_bits(value):
            if not value:
                return 0.0
            counts = {ch: value.count(ch) for ch in set(value)}
            per_char = -sum(n / len(value) * math.log2(n / len(value)) for n in counts.values())
            return per_char * len(value)


        def main():
            base = env("TARGET_URL").rstrip("/")
            with open("security/zap/admin-paths.txt", encoding="utf-8") as fh:
                admin_paths = [line.strip() for line in fh if line.strip().startswith("/")]
            protected = env("PROTECTED_PATH", "/")
            findings, notes = [], []

            def fail(rule, title, path, detail):
                findings.append({"rule": rule, "title": title, "path": path, "detail": detail})

            # Visit the login page first so any pre-login session cookie can be compared after login.
            user = Session(base)
            user.request(env("LOGIN_PATH", "/login"))
            before = user.cookies()
            user, ustatus = login(base, env("ZAP_USER_NAME"), env("ZAP_USER_PASSWORD"), user)
            admin, astatus = login(base, env("ZAP_ADMIN_NAME"), env("ZAP_ADMIN_PASSWORD"))
            if ustatus >= 400 or astatus >= 400:
                print(f"Login failed (user {ustatus}, admin {astatus}); check the test accounts and login settings.")
                return 2

            for path in admin_paths:
                a_status, _, _ = admin.request(path)
                if a_status >= 400:
                    notes.append(f"admin got {a_status} on {path}; is the path right?")
                u_status, u_headers, _ = user.request(path)
                if not denied(u_status, u_headers):
                    fail("broken-access-control", "User role can reach an admin-only path", path, f"user received HTTP {u_status}")
                anon_status, anon_headers, _ = Session(base).request(path)
                if not denied(anon_status, anon_headers):
                    fail("missing-authentication", "Admin-only path reachable without login", path, f"anonymous received HTTP {anon_status}")

            after = user.cookies()
            fixed = [name for name, value in before.items() if after.get(name) == value]
            if fixed:
                fail("session-fixation", "Session cookie not renewed on login", env("LOGIN_PATH", "/login"), f"unchanged cookies: {', '.join(fixed)}")

            tokens = []
            for _ in range(5):
                s, status = login(base, env("ZAP_USER_NAME"), env("ZAP_USER_PASSWORD"))
                values = list(s.cookies().values()) + ([s.bearer] if s.bearer else [])
                if values:
                    tokens.append(max(values, key=len))
            if tokens:
                if len(set(tokens)) < len(tokens):
                    fail("token-reuse", "Session tokens repeat across logins", env("LOGIN_PATH", "/login"), "identical tokens issued")
                weakest = min(entropy_bits(t) for t in tokens)
                if weakest < 64:
                    fail("token-entropy", "Session token entropy below 64 bits", env("LOGIN_PATH", "/login"), f"estimated {weakest:.0f} bits")

            ok_status, _, _ = user.request(protected)
            user.request(env("LOGOUT_PATH", "/logout"), b"", "application/x-www-form-urlencoded", "POST")
            out_status, out_headers, _ = user.request(protected)
            if ok_status < 400 and not denied(out_status, out_headers):
                fail("logout-invalidation", "Session still valid after logout", protected, f"HTTP {out_status} after logout")

            write_reports(findings, notes)
            for f in findings:
                print(f"FAIL {f['rule']}: {f['title']} ({f['path']}): {f['detail']}")
            for n in notes:
                print(f"note: {n}")
            print(f"Access-control check: {len(findings)} finding(s) on {len(admin_paths)} admin-only path(s).")
            return 1 if findings else 0


        def write_reports(findings, notes):
            os.makedirs("reports", exist_ok=True)
            name = f"reports/access-control-{env('DAST_ENV', 'env')}"
            with open(name + ".json", "w", encoding="utf-8") as fh:
                json.dump({"findings": findings, "notes": notes}, fh, indent=2)
            results = [{
                "ruleId": "access-control/" + f["rule"],
                "level": "error",
                "message": {"text": f"{f['title']}: {f['detail']}"},
                "locations": [{"physicalLocation": {"artifactLocation": {"uri": f["path"]}}}],
            } for f in findings]
            with open(name + ".sarif", "w", encoding="utf-8") as fh:
                json.dump({"version": "2.1.0", "runs": [{"tool": {"driver": {"name": "PipelineForge access control"}}, "results": results}]}, fh, indent=2)


        if __name__ == "__main__":
            sys.exit(main())
        """";

    public const string CollectFindings = """"
        #!/usr/bin/env python3
        """Normalises scanner reports into reports/findings.json for ticketing. Generated by PipelineForge.

        Reads SARIF (Gitleaks, Trivy, Snyk, OSV, access control, AI review), ZAP JSON and Sonar issues.
        Each finding gets a stable fingerprint so the ticket step can find an existing ticket.
        Environment: MIN_SEVERITY, MAX_FINDINGS, SOURCES (comma separated), SCOPE.
        """
        import glob
        import hashlib
        import json
        import os
        import re

        SEVERITIES = ["low", "medium", "high", "critical"]
        SOURCE_OF = [
            (r"gitleaks", "secretScan"),
            (r"trivy-fs|snyk\.sarif|osv|dependency-check", "dependencies"),
            (r"trivy-image|snyk-container", "container"),
            (r"trivy-iac|snyk-iac", "iac"),
            (r"hadolint", "dockerfile"),
            (r"access-control", "accessControl"),
            (r"ai-review", "aiReview"),
            (r"zap", "dast"),
            (r"sonar", "sonar"),
        ]


        def source_for(path):
            name = os.path.basename(path)
            for pattern, source in SOURCE_OF:
                if re.search(pattern, name):
                    return source
            return None


        def sarif_severity(result, rule):
            props = (rule or {}).get("properties", {}) | result.get("properties", {})
            score = props.get("security-severity")
            try:
                score = float(score)
                return "critical" if score >= 9 else "high" if score >= 7 else "medium" if score >= 4 else "low"
            except (TypeError, ValueError):
                pass
            return {"error": "high", "warning": "medium", "note": "low"}.get(result.get("level", "warning"), "medium")


        def from_sarif(path, source):
            with open(path, encoding="utf-8") as fh:
                data = json.load(fh)
            for run in data.get("runs", []):
                tool = run.get("tool", {}).get("driver", {}).get("name", source)
                rules = {r.get("id"): r for r in run.get("tool", {}).get("driver", {}).get("rules", []) or []}
                for result in run.get("results", []):
                    rule_id = result.get("ruleId", "unknown")
                    loc = (result.get("locations") or [{}])[0].get("physicalLocation", {})
                    uri = loc.get("artifactLocation", {}).get("uri", "")
                    line = loc.get("region", {}).get("startLine")
                    message = result.get("message", {}).get("text", "")
                    yield {
                        "tool": tool, "source": source, "rule": rule_id,
                        "severity": sarif_severity(result, rules.get(rule_id)),
                        "location": f"{uri}:{line}" if line else uri,
                        "title": f"{tool}: {rule_id}", "description": message,
                    }


        def from_zap(path, source):
            with open(path, encoding="utf-8") as fh:
                data = json.load(fh)
            risk = {"3": "high", "2": "medium", "1": "low", "0": "low"}
            for site in data.get("site", []):
                for alert in site.get("alerts", []):
                    uri = ((alert.get("instances") or [{}])[0]).get("uri", site.get("@name", ""))
                    yield {
                        "tool": "OWASP ZAP", "source": source, "rule": str(alert.get("pluginid", "")),
                        "severity": risk.get(str(alert.get("riskcode", "1")), "low"),
                        "location": re.sub(r"\?.*", "", uri),
                        "title": f"ZAP: {alert.get('alert') or alert.get('name', 'alert')}",
                        "description": re.sub(r"<[^>]+>", "", alert.get("desc", "")) + "\nSolution: " + re.sub(r"<[^>]+>", "", alert.get("solution", "")),
                    }


        def from_sonar(path, source):
            with open(path, encoding="utf-8") as fh:
                data = json.load(fh)
            sev = {"BLOCKER": "critical", "CRITICAL": "high", "MAJOR": "medium", "MINOR": "low", "INFO": "low"}
            for issue in data.get("issues", []):
                yield {
                    "tool": "SonarQube", "source": source, "rule": issue.get("rule", ""),
                    "severity": sev.get(issue.get("severity", "MAJOR"), "medium"),
                    "location": f"{issue.get('component', '')}:{issue.get('line', '')}",
                    "title": f"Sonar: {issue.get('message', '')[:120]}", "description": issue.get("message", ""),
                }


        def main():
            min_sev = SEVERITIES.index(os.environ.get("MIN_SEVERITY", "high"))
            max_findings = int(os.environ.get("MAX_FINDINGS", "10"))
            sources = set(filter(None, os.environ.get("SOURCES", "").split(",")))
            findings, seen = [], set()
            files = sorted(set(glob.glob("reports/**/*.sarif", recursive=True) + glob.glob("reports/**/zap-*.json", recursive=True)
                               + glob.glob("reports/sonar-issues.json")))
            for path in files:
                source = source_for(path)
                if source is None or (sources and source not in sources):
                    continue
                try:
                    reader = from_sonar if path.endswith("sonar-issues.json") else from_zap if path.endswith(".json") else from_sarif
                    for f in reader(path, source):
                        if SEVERITIES.index(f["severity"]) < min_sev:
                            continue
                        f["fingerprint"] = hashlib.sha256(f"{f['tool']}|{f['rule']}|{f['location']}".encode()).hexdigest()[:16]
                        if f["fingerprint"] in seen:
                            continue
                        seen.add(f["fingerprint"])
                        f["summary"] = f"[{f['severity'].upper()}] {f['title']} ({f['location']})"[:240]
                        f["description"] = (f["description"] or "")[:20000] + f"\n\nFound by PipelineForge ({os.environ.get('SCOPE', 'ci')}), build {os.environ.get('BUILD_URL', '')}"
                        findings.append(f)
                except (OSError, ValueError, KeyError) as err:
                    print(f"Skipping {path}: {err}")
            findings.sort(key=lambda f: SEVERITIES.index(f["severity"]), reverse=True)
            os.makedirs("reports", exist_ok=True)
            with open("reports/findings.json", "w", encoding="utf-8") as fh:
                json.dump({"findings": findings[:max_findings], "total": len(findings)}, fh, indent=2)
            print(f"{len(findings)} finding(s) at or above {SEVERITIES[min_sev]}; {min(len(findings), max_findings)} will be ticketed.")


        if __name__ == "__main__":
            main()
        """";

    public const string Provenance = """"
        #!/usr/bin/env python3
        """SLSA v1 provenance predicate per image. Generated by PipelineForge.

        PF_IMAGE_MODULES is "name:Dockerfile,..."; writes reports/attestations/provenance-<name>.json
        for `cosign attest --type slsaprovenance1`.
        """
        import datetime
        import json
        import os
        import re
        import urllib.parse


        def clean_url(url):
            parts = urllib.parse.urlsplit(url or "")
            netloc = parts.hostname or ""
            if parts.port:
                netloc += f":{parts.port}"
            return urllib.parse.urlunsplit((parts.scheme, netloc, parts.path, "", ""))


        def base_images(dockerfile):
            images = []
            try:
                with open(dockerfile, encoding="utf-8") as fh:
                    for line in fh:
                        m = re.match(r"\s*FROM\s+(?:--platform=\S+\s+)?(\S+)", line, re.I)
                        if m and m.group(1).lower() != "scratch" and not re.fullmatch(r"[A-Za-z0-9_-]+", m.group(1)):
                            images.append(m.group(1))
            except OSError:
                pass
            return images


        def iso(ms=None):
            t = datetime.datetime.fromtimestamp(int(ms) / 1000, datetime.timezone.utc) if ms else datetime.datetime.now(datetime.timezone.utc)
            return t.strftime("%Y-%m-%dT%H:%M:%SZ")


        def main():
            os.makedirs("reports/attestations", exist_ok=True)
            repo = clean_url(os.environ.get("GIT_URL", ""))
            commit = os.environ.get("GIT_COMMIT", "")
            for entry in filter(None, os.environ.get("PF_IMAGE_MODULES", "").split(",")):
                name, dockerfile = entry.split(":", 1)
                deps = [{"uri": f"git+{repo}", "digest": {"gitCommit": commit}}] if repo else []
                deps += [{"uri": f"docker://{image}"} for image in base_images(dockerfile)]
                predicate = {
                    "buildDefinition": {
                        "buildType": "https://pipelineforge.dev/jenkins-pipeline/v1",
                        "externalParameters": {"repository": repo, "ref": os.environ.get("BRANCH_NAME", ""), "dockerfile": dockerfile},
                        "internalParameters": {"job": os.environ.get("JOB_NAME", ""), "buildNumber": os.environ.get("BUILD_NUMBER", "")},
                        "resolvedDependencies": deps,
                    },
                    "runDetails": {
                        "builder": {"id": clean_url(os.environ.get("JENKINS_URL", "")) or "jenkins"},
                        "metadata": {
                            "invocationId": clean_url(os.environ.get("BUILD_URL", "")),
                            "startedOn": iso(os.environ.get("PF_BUILD_STARTED")),
                            "finishedOn": iso(),
                        },
                    },
                }
                with open(f"reports/attestations/provenance-{name}.json", "w", encoding="utf-8") as fh:
                    json.dump(predicate, fh, indent=2)
                print(f"Provenance for {name}: {len(deps)} material(s).")


        if __name__ == "__main__":
            main()
        """";
}
